ExerciseDefinition? findExercise(String id) {
  final cleanId = id.trim().toLowerCase();
  for (final exercise in exerciseCatalog) {
    if (exercise.id.toLowerCase() == cleanId) return exercise;
  }
  final noPrefix = cleanId.startsWith('ex_') ? cleanId.substring(3) : cleanId;
  for (final exercise in exerciseCatalog) {
    final cur = exercise.id.toLowerCase();
    final curNoPrefix = cur.startsWith('ex_') ? cur.substring(3) : cur;
    if (curNoPrefix == noPrefix) return exercise;
  }
  return null;
}

ExerciseDefinition? findExerciseByName(String name) {
  final cleanName = name.trim().toLowerCase();
  for (final exercise in exerciseCatalog) {
    if (exercise.name.toLowerCase() == cleanName ||
        exercise.nameVi.toLowerCase() == cleanName ||
        exercise.id.toLowerCase() == cleanName) {
      return exercise;
    }
  }
  for (final exercise in exerciseCatalog) {
    if (exercise.name.toLowerCase().contains(cleanName) ||
        exercise.nameVi.toLowerCase().contains(cleanName) ||
        cleanName.contains(exercise.name.toLowerCase()) ||
        cleanName.contains(exercise.nameVi.toLowerCase())) {
      return exercise;
    }
  }
  return null;
}

/// Fallback resolver to get authentic Free Exercise DB CDN image for any exercise name or slug
String resolveExerciseCdnImage(String? slugOrName) {
  if (slugOrName == null || slugOrName.trim().isEmpty) {
    return 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400&auto=format&fit=crop&q=80';
  }
  final found = findExerciseByName(slugOrName) ?? findExercise(slugOrName);
  if (found != null && found.thumbnailUrl.isNotEmpty) {
    return found.thumbnailUrl;
  }
  return 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400&auto=format&fit=crop&q=80';
}

/// Fallback resolver to get authentic Free Exercise DB CDN secondary motion image for any exercise
String? resolveExerciseCdnVideo(String? slugOrName) {
  if (slugOrName == null || slugOrName.trim().isEmpty) return null;
  final found = findExerciseByName(slugOrName) ?? findExercise(slugOrName);
  return found?.videoUrl;
}

List<ExerciseDefinition> replacementCandidates({
  required String originalExerciseId,
  required Set<EquipmentType> availableEquipment,
}) {
  final original = findExercise(originalExerciseId);
  if (original == null) return const [];

  final preferredIds = originalExerciseId == 'ex1'
      ? const [
          'ex_neutral_db_press',
          'ex_chest_press_machine',
          'ex_pec_deck_fly',
        ]
      : exerciseCatalog
            .where(
              (item) =>
                  item.id != originalExerciseId &&
                  item.primaryMuscle == original.primaryMuscle,
            )
            .map((item) => item.id)
            .toList();

  return preferredIds
      .map(findExercise)
      .whereType<ExerciseDefinition>()
      .where((item) => availableEquipment.contains(item.equipment))
      .take(3)
      .toList();
}
